#include "5c0fcca8c23873b9_party_health.hpp"
namespace recovered_party_health{static bool member(U s,Ports&p){U count=p.read(p.party(p.client()));for(U i=0;static_cast<std::int32_t>(i)<static_cast<std::int32_t>(count);++i){U entry=p.character(p.party(p.client()),i);U id=p.client_id(p.client(),p.read(s+4));if(entry&&p.read(entry+4)==id)return true;}return false;}U dead(U s,Ports&p){return member(s,p)?0:p.base_dead(s);}U incapacitated(U s,Ports&p){return member(s,p)?static_cast<std::int16_t>(p.current(s))<=0:0;}U render(U s,Ports&p){if(!p.read(s+0x224)){U id=p.client_id(p.client(),p.read(s+4));U object=p.lookup(p.client(),id);if(object){U r=p.renderer(object);p.write(s+0x224,r);if(r)p.attach(r,s);}}return p.read(s+0x224);}}
